id: vuln-conform-4819d51b
languages:
  - typescript
message: Detect improper modification of object prototype attributes in getPaths function.
severity: ERROR
pattern: |
  function getPaths\(name: string \| undefined\): Array<string \| number> {
    if \(!name\) {
      return [];
    }

    return name
      .split(/\.|(\[\d*\])/)
      .reduce<Array<string \| number>>((result, segment) => {
        if \(typeof segment !== 'undefined' && segment !== '' && segment !== '__proto__' && segment !== 'constructor' && segment !== 'prototype' \) {
          if \(segment.startsWith('[') && segment.endsWith(']')\) {
            const index = segment.slice\(1, -1\);

            result.push\(Number(index)\);
          } else {
            result.push\(segment\);
          }
        }
        return result;
      }, []);
  }
```

